import React, { useState, useEffect } from 'react';
import {
  Shield, Users, ClipboardList, Plus, Check, X, AlertTriangle,
  LogOut, Search, TrendingUp, Clock, Trash2, ChevronRight, Loader2,
  Calendar, Eye, Copy, Download, Lightbulb
} from 'lucide-react';
import { supabase } from './supabaseClient.js';

const C = {
  bg: '#0B0B0B',
  panel: '#181313',
  panelAlt: '#221A1A',
  border: '#3D2C2C',
  borderLight: '#523C3C',
  olive: '#5B5E62',
  oliveLight: '#9DA0A4',
  amber: '#C31F2A',
  amberDim: '#451317',
  gold: '#C98A34',
  bone: '#F3F0E9',
  boneMuted: '#9C9490',
  success: '#5D8C60',
  danger: '#C31F2A',
};

const LOGO_SRC = 'data:image/png;base64,';

const PRIORITIES = {
  'רגיל': { color: C.oliveLight, ring: '#302626' },
  'דחוף': { color: C.gold, ring: '#3D2A14' },
  'קריטי': { color: C.amber, ring: '#3A1216' },
};

const DUTY_STATUSES = ['בבסיס', 'בשמירה', 'בחופשה', 'במחלה'];
const TEAMS = ['1א', '1ב', '1ג', '2א', '2ב', 'מפ״יק'];
const STORAGE_KEY = 'roster-data-v4';

function uid() { return Date.now().toString(36) + Math.random().toString(36).slice(2, 8); }
function todayStr() { return new Date().toISOString().slice(0, 10); }
function fmtDate(d) {
  if (!d) return '';
  const dt = new Date(d + 'T00:00:00');
  return dt.toLocaleDateString('he-IL', { day: '2-digit', month: '2-digit' });
}
function emptyGuard() { return { date: todayStr(), posts: [], slots: [], assignments: {} }; }
function isOverdue(task) {
  if (task.status !== 'פתוח' || !task.dueDate) return false;
  const deadline = new Date(`${task.dueDate}T${task.dueTime || '23:59'}`);
  return deadline.getTime() < Date.now();
}

function buildGuardText(guard, soldiers) {
  const soldierMap = Object.fromEntries(soldiers.map(s => [s.id, s]));
  let text = `רשימת שמירה — ${fmtDate(guard.date)}\n`;
  guard.posts.forEach(post => {
    text += `\n📍 ${post.name}\n`;
    guard.slots.forEach(slot => {
      const sid = guard.assignments[`${slot.id}|${post.id}`];
      const s = sid ? soldierMap[sid] : null;
      const who = s ? `${s.name}${s.phone ? ' — ' + s.phone : ''}` : '—';
      text += `${slot.label} — ${who}\n`;
    });
  });
  return text.trim();
}

function downloadGuardCSV(guard, soldiers) {
  const soldierMap = Object.fromEntries(soldiers.map(s => [s.id, s]));
  const rows = [['עמדה', 'שעה', 'שם חייל', 'טלפון']];
  guard.posts.forEach(post => {
    guard.slots.forEach(slot => {
      const sid = guard.assignments[`${slot.id}|${post.id}`];
      const s = sid ? soldierMap[sid] : null;
      rows.push([post.name, slot.label, s ? s.name : '', s ? (s.phone || '') : '']);
    });
  });
  const csv = rows.map(r => r.map(c => `"${String(c || '').replace(/"/g, '""')}"`).join(',')).join('\n');
  const blob = new Blob(['\uFEFF' + csv], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `רשימת_שמירה_${guard.date}.csv`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

const GlobalStyle = () => (
  <style>{`
    @import url('https://fonts.googleapis.com/css2?family=Assistant:wght@300;400;500;600;700;800&family=Suez+One&family=Rubik:wght@400;500;600;700;800&display=swap');
    .rt-app * { box-sizing: border-box; }
    .rt-app { font-family: 'Assistant', sans-serif; }
    .rt-mono { font-family: 'Rubik', sans-serif; font-variant-numeric: tabular-nums; }
    .rt-display { font-family: 'Suez One', serif; font-weight: 400; }
    .rt-card {
      clip-path: polygon(0 0, calc(100% - 14px) 0, 100% 14px, 100% 100%, 0 100%);
    }
    .rt-scroll::-webkit-scrollbar { width: 6px; }
    .rt-scroll::-webkit-scrollbar-thumb { background: ${C.border}; border-radius: 3px; }
    .rt-fade-in { animation: rtFadeIn .25s ease both; }
    @keyframes rtFadeIn { from { opacity: 0; transform: translateY(4px);} to { opacity:1; transform:none; } }
  `}</style>
);

const APP_PASSCODE = import.meta.env.VITE_APP_PASSCODE || '';

// ---- DB row <-> app shape mapping helpers ----------------------------
function mapTask(row) {
  return {
    id: row.id,
    groupId: row.group_id,
    title: row.title,
    description: row.description || '',
    dueDate: row.due_date || '',
    dueTime: row.due_time ? row.due_time.slice(0, 5) : '',
    priority: row.priority,
    assignedTo: row.assigned_to,
    status: row.status,
    createdAt: row.created_at,
    completedAt: row.completed_at,
  };
}
function mapSoldier(row) {
  return { id: row.id, name: row.name, team: row.team, phone: row.phone || '', status: row.status };
}
function mapScheduleItem(row) {
  return { id: row.id, time: row.time, title: row.title, note: row.note || '' };
}
function mapLesson(row) {
  return {
    id: row.id,
    authorId: row.author_id,
    authorName: row.author_name,
    setLabel: row.set_label || '',
    text: row.text,
    createdAt: row.created_at,
  };
}

export default function App() {
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState('');
  const [unlocked, setUnlocked] = useState(!APP_PASSCODE);
  const [passInput, setPassInput] = useState('');

  const [soldiers, setSoldiers] = useState([]);
  const [tasks, setTasks] = useState([]);
  const [schedule, setSchedule] = useState([]);
  const [guard, setGuard] = useState(emptyGuard());
  const [lessons, setLessons] = useState([]);

  const [role, setRole] = useState(null);
  const [currentSoldierId, setCurrentSoldierId] = useState(null);
  const [syncing, setSyncing] = useState(false);

  useEffect(() => {
    if (unlocked) loadAll();
  }, [unlocked]);

  async function loadAll() {
    setLoading(true);
    setLoadError('');
    try {
      const [
        soldiersRes, tasksRes, scheduleRes,
        guardSettingsRes, guardPostsRes, guardSlotsRes, guardAssignmentsRes,
        lessonsRes,
      ] = await Promise.all([
        supabase.from('soldiers').select('*').order('created_at'),
        supabase.from('tasks').select('*'),
        supabase.from('schedule_items').select('*').order('time'),
        supabase.from('guard_settings').select('*').eq('id', 1).maybeSingle(),
        supabase.from('guard_posts').select('*').order('created_at'),
        supabase.from('guard_slots').select('*').order('label'),
        supabase.from('guard_assignments').select('*'),
        supabase.from('lessons').select('*').order('created_at', { ascending: false }),
      ]);

      for (const res of [soldiersRes, tasksRes, scheduleRes, guardPostsRes, guardSlotsRes, guardAssignmentsRes, lessonsRes]) {
        if (res.error) throw res.error;
      }
      if (guardSettingsRes.error) throw guardSettingsRes.error;

      setSoldiers((soldiersRes.data || []).map(mapSoldier));
      setTasks((tasksRes.data || []).map(mapTask));
      setSchedule((scheduleRes.data || []).map(mapScheduleItem));

      const assignments = {};
      (guardAssignmentsRes.data || []).forEach(row => {
        assignments[`${row.slot_id}|${row.post_id}`] = row.soldier_id;
      });
      setGuard({
        date: (guardSettingsRes.data && guardSettingsRes.data.date) || todayStr(),
        posts: (guardPostsRes.data || []).map(p => ({ id: p.id, name: p.name })),
        slots: (guardSlotsRes.data || []).map(s => ({ id: s.id, label: s.label })),
        assignments,
      });

      setLessons((lessonsRes.data || []).map(mapLesson));
    } catch (err) {
      console.error(err);
      setLoadError(err.message || 'שגיאה בטעינת הנתונים מהשרת.');
    } finally {
      setLoading(false);
    }
  }

  async function withSync(fn) {
    setSyncing(true);
    try {
      await fn();
    } catch (err) {
      console.error(err);
      window.alert('פעולה נכשלה: ' + (err.message || 'שגיאת שרת'));
    } finally {
      setSyncing(false);
    }
  }

  // ---- Soldiers ---------------------------------------------------
  function addSoldier(soldier) {
    withSync(async () => {
      const { data, error } = await supabase
        .from('soldiers')
        .insert({ name: soldier.name, team: soldier.team, phone: soldier.phone || null, status: 'בבסיס' })
        .select()
        .single();
      if (error) throw error;
      setSoldiers(prev => [...prev, mapSoldier(data)]);
    });
  }

  function removeSoldier(id) {
    withSync(async () => {
      const { error } = await supabase.from('soldiers').delete().eq('id', id);
      if (error) throw error;
      setSoldiers(prev => prev.filter(s => s.id !== id));
      setTasks(prev => prev.filter(t => t.assignedTo !== id));
      setGuard(prev => {
        const assignments = { ...prev.assignments };
        Object.keys(assignments).forEach(k => { if (assignments[k] === id) delete assignments[k]; });
        return { ...prev, assignments };
      });
    });
  }

  function setSoldierStatus(id, status) {
    withSync(async () => {
      const { error } = await supabase.from('soldiers').update({ status }).eq('id', id);
      if (error) throw error;
      setSoldiers(prev => prev.map(s => s.id === id ? { ...s, status } : s));
    });
  }

  // ---- Tasks --------------------------------------------------------
  function addTasks(newTasks) {
    withSync(async () => {
      const rows = newTasks.map(t => ({
        group_id: t.groupId,
        title: t.title,
        description: t.description || null,
        due_date: t.dueDate || null,
        due_time: t.dueTime || null,
        priority: t.priority,
        assigned_to: t.assignedTo,
        status: 'פתוח',
      }));
      const { data, error } = await supabase.from('tasks').insert(rows).select();
      if (error) throw error;
      setTasks(prev => [...prev, ...(data || []).map(mapTask)]);
    });
  }

  function toggleTask(taskId) {
    withSync(async () => {
      const current = tasks.find(t => t.id === taskId);
      if (!current) return;
      const nextStatus = current.status === 'הושלם' ? 'פתוח' : 'הושלם';
      const completedAt = nextStatus === 'הושלם' ? new Date().toISOString() : null;
      const { error } = await supabase.from('tasks').update({ status: nextStatus, completed_at: completedAt }).eq('id', taskId);
      if (error) throw error;
      setTasks(prev => prev.map(t => t.id === taskId ? { ...t, status: nextStatus, completedAt } : t));
    });
  }

  function removeTask(taskId) {
    withSync(async () => {
      const { error } = await supabase.from('tasks').delete().eq('id', taskId);
      if (error) throw error;
      setTasks(prev => prev.filter(t => t.id !== taskId));
    });
  }

  // ---- Daily schedule -------------------------------------------------
  function addScheduleItem(item) {
    withSync(async () => {
      const { data, error } = await supabase
        .from('schedule_items')
        .insert({ time: item.time, title: item.title, note: item.note || null })
        .select()
        .single();
      if (error) throw error;
      setSchedule(prev => [...prev, mapScheduleItem(data)].sort((a, b) => a.time.localeCompare(b.time)));
    });
  }

  function removeScheduleItem(id) {
    withSync(async () => {
      const { error } = await supabase.from('schedule_items').delete().eq('id', id);
      if (error) throw error;
      setSchedule(prev => prev.filter(s => s.id !== id));
    });
  }

  // ---- Guard duty -----------------------------------------------------
  function setGuardDate(date) {
    withSync(async () => {
      const { error } = await supabase.from('guard_settings').update({ date }).eq('id', 1);
      if (error) throw error;
      setGuard(prev => ({ ...prev, date }));
    });
  }

  function addGuardPost(name) {
    withSync(async () => {
      const { data, error } = await supabase.from('guard_posts').insert({ name }).select().single();
      if (error) throw error;
      setGuard(prev => ({ ...prev, posts: [...prev.posts, { id: data.id, name: data.name }] }));
    });
  }

  function removeGuardPost(id) {
    withSync(async () => {
      const { error } = await supabase.from('guard_posts').delete().eq('id', id);
      if (error) throw error;
      setGuard(prev => {
        const assignments = { ...prev.assignments };
        Object.keys(assignments).forEach(k => { if (k.endsWith('|' + id)) delete assignments[k]; });
        return { ...prev, posts: prev.posts.filter(p => p.id !== id), assignments };
      });
    });
  }

  function addGuardSlot(label) {
    withSync(async () => {
      const { data, error } = await supabase.from('guard_slots').insert({ label }).select().single();
      if (error) throw error;
      setGuard(prev => ({
        ...prev,
        slots: [...prev.slots, { id: data.id, label: data.label }].sort((a, b) => a.label.localeCompare(b.label)),
      }));
    });
  }

  function removeGuardSlot(id) {
    withSync(async () => {
      const { error } = await supabase.from('guard_slots').delete().eq('id', id);
      if (error) throw error;
      setGuard(prev => {
        const assignments = { ...prev.assignments };
        Object.keys(assignments).forEach(k => { if (k.startsWith(id + '|')) delete assignments[k]; });
        return { ...prev, slots: prev.slots.filter(s => s.id !== id), assignments };
      });
    });
  }

  function generateGuardSlots(hours) {
    if (guard.slots.length > 0 && !window.confirm('פעולה זו תחליף את טבלת השעות הקיימת ותמחק את השיבוצים. להמשיך?')) return;
    withSync(async () => {
      const existingIds = guard.slots.map(s => s.id);
      if (existingIds.length) {
        const { error: delErr } = await supabase.from('guard_slots').delete().in('id', existingIds);
        if (delErr) throw delErr;
      }
      const rows = [];
      for (let h = 0; h < 24; h += hours) {
        const start = String(h).padStart(2, '0') + ':00';
        const end = String((h + hours) % 24).padStart(2, '0') + ':00';
        rows.push({ label: `${start}–${end}` });
      }
      const { data, error } = await supabase.from('guard_slots').insert(rows).select();
      if (error) throw error;
      setGuard(prev => ({
        ...prev,
        slots: (data || []).map(s => ({ id: s.id, label: s.label })).sort((a, b) => a.label.localeCompare(b.label)),
        assignments: {},
      }));
    });
  }

  function setGuardAssignment(slotId, postId, soldierId) {
    withSync(async () => {
      if (soldierId) {
        const { error } = await supabase
          .from('guard_assignments')
          .upsert({ slot_id: slotId, post_id: postId, soldier_id: soldierId }, { onConflict: 'slot_id,post_id' });
        if (error) throw error;
      } else {
        const { error } = await supabase
          .from('guard_assignments')
          .delete()
          .eq('slot_id', slotId)
          .eq('post_id', postId);
        if (error) throw error;
      }
      setGuard(prev => {
        const assignments = { ...prev.assignments };
        const key = `${slotId}|${postId}`;
        if (soldierId) assignments[key] = soldierId; else delete assignments[key];
        return { ...prev, assignments };
      });
    });
  }

  // ---- Lessons learned --------------------------------------------------
  function addLesson(lesson) {
    withSync(async () => {
      const { data, error } = await supabase
        .from('lessons')
        .insert({
          author_id: lesson.authorId || null,
          author_name: lesson.authorName || null,
          set_label: lesson.setLabel || null,
          text: lesson.text,
        })
        .select()
        .single();
      if (error) throw error;
      setLessons(prev => [mapLesson(data), ...prev]);
    });
  }

  function removeLesson(id) {
    withSync(async () => {
      const { error } = await supabase.from('lessons').delete().eq('id', id);
      if (error) throw error;
      setLessons(prev => prev.filter(l => l.id !== id));
    });
  }

  function logout() { setRole(null); setCurrentSoldierId(null); }

  if (!unlocked) {
    return (
      <div className="rt-app" dir="rtl" style={{ background: C.bg, minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', color: C.bone, padding: 24 }}>
        <GlobalStyle />
        <form
          onSubmit={e => { e.preventDefault(); if (passInput === APP_PASSCODE) setUnlocked(true); else window.alert('קוד שגוי'); }}
          style={{ background: C.panel, border: `1px solid ${C.border}`, borderRadius: 10, padding: 24, width: '100%', maxWidth: 320, display: 'flex', flexDirection: 'column', gap: 14 }}
        >
          <img src={LOGO_SRC} alt="סמל" style={{ width: 72, height: 72, objectFit: 'contain', margin: '0 auto' }} />
          <div style={{ textAlign: 'center', fontSize: 13, color: C.boneMuted }}>הזן קוד גישה</div>
          <input
            type="password" autoFocus value={passInput} onChange={e => setPassInput(e.target.value)}
            style={{ background: C.panelAlt, border: `1px solid ${C.borderLight}`, borderRadius: 6, padding: '10px 12px', color: C.bone, fontSize: 14, textAlign: 'center' }}
          />
          <button type="submit" style={{ background: C.amber, color: C.bone, border: 'none', borderRadius: 8, padding: '10px 16px', fontWeight: 700, cursor: 'pointer' }}>
            כניסה
          </button>
        </form>
      </div>
    );
  }

  if (loading) {
    return (
      <div className="rt-app" dir="rtl" style={{ background: C.bg, minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', color: C.bone }}>
        <GlobalStyle />
        <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 10 }}>
          <Loader2 className="animate-spin" size={28} style={{ color: C.amber }} />
          <span className="rt-mono" style={{ fontSize: 12, letterSpacing: 1, color: C.boneMuted }}>טוען נתונים...</span>
        </div>
      </div>
    );
  }

  if (loadError) {
    return (
      <div className="rt-app" dir="rtl" style={{ background: C.bg, minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', color: C.bone, padding: 24 }}>
        <GlobalStyle />
        <div style={{ maxWidth: 420, textAlign: 'center', display: 'flex', flexDirection: 'column', gap: 14 }}>
          <AlertTriangle size={28} style={{ color: C.danger, margin: '0 auto' }} />
          <div style={{ fontWeight: 700 }}>לא הצלחנו להתחבר לשרת</div>
          <div style={{ fontSize: 13, color: C.boneMuted }}>{loadError}</div>
          <div style={{ fontSize: 12, color: C.boneMuted }}>ודאו ש-VITE_SUPABASE_URL ו-VITE_SUPABASE_ANON_KEY מוגדרים נכון בקובץ .env, ושה-schema הורץ בפרויקט ה-Supabase.</div>
          <button onClick={loadAll} style={{ background: C.amber, color: C.bone, border: 'none', borderRadius: 8, padding: '10px 16px', fontWeight: 700, cursor: 'pointer' }}>
            נסה שוב
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="rt-app" dir="rtl" style={{ background: C.bg, minHeight: '100vh', color: C.bone }}>
      <GlobalStyle />
      {!role && (
        <LoginScreen soldiers={soldiers} onAdmin={() => setRole('admin')}
          onSoldier={(id) => { setCurrentSoldierId(id); setRole('soldier'); }} />
      )}
      {role === 'admin' && (
        <AdminView
          soldiers={soldiers} tasks={tasks} schedule={schedule} guard={guard} lessons={lessons} syncing={syncing}
          onAddSoldier={addSoldier} onRemoveSoldier={removeSoldier}
          onSetStatus={setSoldierStatus} onAddTasks={addTasks}
          onToggleTask={toggleTask} onRemoveTask={removeTask}
          onAddScheduleItem={addScheduleItem} onRemoveScheduleItem={removeScheduleItem}
          onSetGuardDate={setGuardDate} onAddGuardPost={addGuardPost} onRemoveGuardPost={removeGuardPost}
          onAddGuardSlot={addGuardSlot} onRemoveGuardSlot={removeGuardSlot}
          onGenerateGuardSlots={generateGuardSlots} onSetGuardAssignment={setGuardAssignment}
          onAddLesson={addLesson} onRemoveLesson={removeLesson}
          onLogout={logout}
        />
      )}
      {role === 'soldier' && (
        <SoldierView
          soldier={soldiers.find(s => s.id === currentSoldierId)}
          tasks={tasks.filter(t => t.assignedTo === currentSoldierId)}
          schedule={schedule} guard={guard} lessons={lessons}
          onToggleTask={toggleTask} onAddLesson={addLesson} onRemoveLesson={removeLesson}
          onLogout={logout}
        />
      )}
    </div>
  );
}
function LoginScreen({ soldiers, onAdmin, onSoldier }) {
  const [pickerOpen, setPickerOpen] = useState(false);
  const [q, setQ] = useState('');
  const filtered = soldiers.filter(s => s.name.toLowerCase().includes(q.toLowerCase()));

  return (
    <div className="rt-fade-in" style={{
      minHeight: '100vh', display: 'flex', flexDirection: 'column', alignItems: 'center',
      justifyContent: 'center', padding: 24,
      backgroundImage: `repeating-linear-gradient(45deg, ${C.panel} 0, ${C.panel} 1px, transparent 1px, transparent 22px)`
    }}>
      <img src={LOGO_SRC} alt="סמל היחידה" style={{ width: 128, height: 128, objectFit: 'contain', marginBottom: 14, filter: 'drop-shadow(0 4px 18px rgba(195,31,42,0.35))' }} />
      <span className="rt-mono" style={{ fontSize: 12, letterSpacing: 3, color: C.boneMuted, marginBottom: 6 }}>קורס מפקדים 164</span>
      <h1 className="rt-display" style={{ fontSize: 32, margin: '4px 0 28px', letterSpacing: 0.5, textAlign: 'center' }}>ניהול סד״כ קורס מפקדים 164</h1>

      {!pickerOpen && (
        <div style={{ display: 'flex', gap: 14, flexWrap: 'wrap', justifyContent: 'center' }}>
          <button onClick={onAdmin} style={btnPrimary()}>
            <Shield size={18} /> כניסה כמפקד/מנהל
          </button>
          <button onClick={() => setPickerOpen(true)} style={btnSecondary()}>
            <Users size={18} /> כניסה כחייל
          </button>
        </div>
      )}

      {pickerOpen && (
        <div style={{ width: '100%', maxWidth: 380 }} className="rt-fade-in">
          <div style={{ display: 'flex', alignItems: 'center', gap: 8, background: C.panel, border: `1px solid ${C.border}`, borderRadius: 8, padding: '8px 12px', marginBottom: 12 }}>
            <Search size={16} style={{ color: C.boneMuted }} />
            <input autoFocus value={q} onChange={e => setQ(e.target.value)} placeholder="חיפוש שם..."
              style={{ background: 'transparent', border: 'none', outline: 'none', color: C.bone, width: '100%', fontFamily: 'inherit' }} />
          </div>
          <div className="rt-scroll" style={{ maxHeight: 320, overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: 8 }}>
            {filtered.length === 0 && (
              <div style={{ textAlign: 'center', color: C.boneMuted, fontSize: 13, padding: 20 }}>
                {soldiers.length === 0 ? 'טרם נוספו חיילים למערכת. יש לפנות למנהל.' : 'לא נמצאו תוצאות'}
              </div>
            )}
            {filtered.map(s => (
              <button key={s.id} onClick={() => onSoldier(s.id)} style={{
                display: 'flex', alignItems: 'center', justifyContent: 'space-between', width: '100%',
                background: C.panel, border: `1px solid ${C.border}`, borderRadius: 8, padding: '12px 14px',
                color: C.bone, cursor: 'pointer', textAlign: 'right'
              }}>
                <div>
                  <div style={{ fontWeight: 600 }}>{s.name}</div>
                  <div className="rt-mono" style={{ fontSize: 11, color: C.boneMuted }}>צוות {s.team}</div>
                </div>
                <ChevronRight size={16} style={{ color: C.boneMuted }} />
              </button>
            ))}
          </div>
          <button onClick={() => setPickerOpen(false)} style={{ ...btnGhost(), marginTop: 14, width: '100%', justifyContent: 'center' }}>חזרה</button>
        </div>
      )}
    </div>
  );
}

function btnPrimary() {
  return { display: 'flex', alignItems: 'center', gap: 8, background: C.amber, color: C.bone, border: 'none', borderRadius: 8, padding: '12px 20px', fontWeight: 700, fontSize: 14, cursor: 'pointer' };
}
function btnSecondary() {
  return { display: 'flex', alignItems: 'center', gap: 8, background: C.panel, color: C.bone, border: `1px solid ${C.borderLight}`, borderRadius: 8, padding: '12px 20px', fontWeight: 600, fontSize: 14, cursor: 'pointer' };
}
function btnGhost() {
  return { display: 'flex', alignItems: 'center', gap: 6, background: 'transparent', color: C.boneMuted, border: `1px solid ${C.border}`, borderRadius: 8, padding: '8px 14px', fontSize: 13, cursor: 'pointer' };
}

function Header({ title, subtitle, onLogout, syncing }) {
  return (
    <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '16px 24px', borderBottom: `1px solid ${C.border}`, background: C.panel }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
        <img src={LOGO_SRC} alt="סמל" style={{ width: 30, height: 30, objectFit: 'contain' }} />
        <div>
          <div className="rt-display" style={{ fontSize: 17 }}>{title}</div>
          {subtitle && <div className="rt-mono" style={{ fontSize: 11, color: C.boneMuted }}>{subtitle}</div>}
        </div>
      </div>
      <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
        {syncing && <Loader2 size={14} className="animate-spin" style={{ color: C.boneMuted }} />}
        <button onClick={onLogout} style={btnGhost()}><LogOut size={14} /> יציאה</button>
      </div>
    </div>
  );
}

function StatCard({ icon: Icon, label, value, accent }) {
  return (
    <div style={{ background: C.panel, border: `1px solid ${C.border}`, borderRadius: 10, padding: 16, flex: 1, minWidth: 130 }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 10 }}>
        <Icon size={15} style={{ color: accent || C.boneMuted }} />
        <span style={{ fontSize: 12, color: C.boneMuted }}>{label}</span>
      </div>
      <div className="rt-mono" style={{ fontSize: 26, fontWeight: 700, color: accent || C.bone }}>{value}</div>
    </div>
  );
}

function TaskCard({ task, soldierName, onToggle, onRemove, showSoldier }) {
  const overdue = isOverdue(task);
  const p = PRIORITIES[task.priority] || PRIORITIES['רגיל'];
  const done = task.status === 'הושלם';
  return (
    <div className="rt-card rt-fade-in" style={{
      background: C.panel, borderRight: `3px solid ${done ? C.success : p.color}`,
      border: `1px solid ${overdue ? C.danger : C.border}`, padding: '12px 16px', display: 'flex',
      alignItems: 'flex-start', gap: 12, opacity: done ? 0.65 : 1
    }}>
      <button onClick={() => onToggle(task.id)} style={{
        width: 24, height: 24, minWidth: 24, borderRadius: '50%', border: `2px solid ${done ? C.success : C.borderLight}`,
        background: done ? C.success : 'transparent', display: 'flex', alignItems: 'center', justifyContent: 'center',
        cursor: 'pointer', marginTop: 2
      }}>
        {done && <Check size={13} color="#12140E" />}
      </button>
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }}>
          <span style={{ fontWeight: 600, fontSize: 14, textDecoration: done ? 'line-through' : 'none' }}>{task.title}</span>
          <span className="rt-mono" style={{ fontSize: 10, padding: '2px 7px', borderRadius: 5, background: p.ring, color: p.color, fontWeight: 700 }}>{task.priority}</span>
          {overdue && <span style={{ display: 'flex', alignItems: 'center', gap: 4, fontSize: 10, color: C.danger }}><AlertTriangle size={11} /> באיחור</span>}
        </div>
        {task.description && <div style={{ fontSize: 12.5, color: C.boneMuted, marginTop: 4 }}>{task.description}</div>}
        <div style={{ display: 'flex', gap: 12, marginTop: 6, alignItems: 'center' }}>
          {task.dueDate && <span className="rt-mono" style={{ fontSize: 11, color: C.boneMuted, display: 'flex', alignItems: 'center', gap: 4 }}><Clock size={11} /> {fmtDate(task.dueDate)}{task.dueTime && ` · ${task.dueTime}`}</span>}
          {showSoldier && <span style={{ fontSize: 11, color: C.oliveLight }}>{soldierName}</span>}
        </div>
      </div>
      {onRemove && (
        <button onClick={() => onRemove(task.id)} style={{ background: 'transparent', border: 'none', color: C.boneMuted, cursor: 'pointer' }}>
          <Trash2 size={14} />
        </button>
      )}
    </div>
  );
}

function SoldierView({ soldier, tasks, schedule, guard, lessons, onToggleTask, onAddLesson, onRemoveLesson, onLogout }) {
  if (!soldier) return null;
  const today = todayStr();
  const overdue = tasks.filter(t => isOverdue(t));
  const dueToday = tasks.filter(t => t.status === 'פתוח' && t.dueDate === today && !isOverdue(t));
  const upcoming = tasks.filter(t => t.status === 'פתוח' && (!t.dueDate || t.dueDate > today) && !isOverdue(t));
  const completed = tasks.filter(t => t.status === 'הושלם');
  const total = tasks.length;
  const pct = total ? Math.round((completed.length / total) * 100) : 0;

  const myShifts = Object.entries(guard.assignments)
    .filter(([, sid]) => sid === soldier.id)
    .map(([key]) => {
      const [slotId, postId] = key.split('|');
      const slot = guard.slots.find(s => s.id === slotId);
      const post = guard.posts.find(p => p.id === postId);
      return slot && post ? { label: slot.label, post: post.name, order: slot.label } : null;
    })
    .filter(Boolean)
    .sort((a, b) => a.order.localeCompare(b.order));

  return (
    <div>
      <Header title={soldier.name} subtitle={`צוות ${soldier.team} · ${soldier.status}`} onLogout={onLogout} />
      <div style={{ maxWidth: 720, margin: '0 auto', padding: 24 }}>
        <div style={{ background: C.panel, border: `1px solid ${C.border}`, borderRadius: 10, padding: 16, marginBottom: 24 }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 12, color: C.boneMuted, marginBottom: 8 }}>
            <span>אחוז השלמת משימות</span>
            <span className="rt-mono">{pct}%</span>
          </div>
          <div style={{ height: 8, background: C.panelAlt, borderRadius: 4, overflow: 'hidden' }}>
            <div style={{ height: '100%', width: `${pct}%`, background: C.amber, transition: 'width .3s' }} />
          </div>
        </div>

        {schedule.length > 0 && (
          <div style={{ marginBottom: 24 }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: 10 }}>
              <Calendar size={14} style={{ color: C.amber }} />
              <span style={{ fontSize: 12, fontWeight: 700, color: C.amber, letterSpacing: 0.5 }}>לו״ז היום</span>
            </div>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
              {schedule.map(item => (
                <div key={item.id} className="rt-card" style={{ background: C.panel, border: `1px solid ${C.border}`, borderRight: `3px solid ${C.amber}`, padding: '10px 14px', display: 'flex', gap: 12, alignItems: 'baseline' }}>
                  <span className="rt-mono" style={{ fontSize: 12, color: C.amber, minWidth: 44 }}>{item.time}</span>
                  <div>
                    <div style={{ fontSize: 13.5, fontWeight: 600 }}>{item.title}</div>
                    {item.note && <div style={{ fontSize: 12, color: C.boneMuted, marginTop: 2 }}>{item.note}</div>}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {myShifts.length > 0 && (
          <div style={{ marginBottom: 24 }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: 10 }}>
              <Eye size={14} style={{ color: C.danger }} />
              <span style={{ fontSize: 12, fontWeight: 700, color: C.danger, letterSpacing: 0.5 }}>שיבוצי שמירה · {fmtDate(guard.date)}</span>
            </div>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
              {myShifts.map((sh, i) => (
                <div key={i} className="rt-card" style={{ background: C.panel, border: `1px solid ${C.border}`, borderRight: `3px solid ${C.danger}`, padding: '10px 14px', display: 'flex', gap: 12, alignItems: 'baseline' }}>
                  <span className="rt-mono" style={{ fontSize: 12, color: C.danger, minWidth: 90 }}>{sh.label}</span>
                  <span style={{ fontSize: 13.5, fontWeight: 600 }}>{sh.post}</span>
                </div>
              ))}
            </div>
          </div>
        )}

        {overdue.length > 0 && <Section title="באיחור" icon={AlertTriangle} color={C.danger} tasks={overdue} onToggleTask={onToggleTask} />}
        <Section title="להיום" icon={Clock} color={C.amber} tasks={dueToday} onToggleTask={onToggleTask} empty="אין משימות שנקבעו להיום" />
        <Section title="בהמשך" icon={ClipboardList} color={C.oliveLight} tasks={upcoming} onToggleTask={onToggleTask} empty="אין משימות עתידיות" />
        {completed.length > 0 && <Section title="הושלמו" icon={Check} color={C.success} tasks={completed} onToggleTask={onToggleTask} />}

        <div style={{ marginTop: 32, paddingTop: 24, borderTop: `1px solid ${C.border}` }}>
          <LessonsTab lessons={lessons} onAdd={onAddLesson} onRemove={onRemoveLesson} authorId={soldier.id} authorName={soldier.name} canRemoveAny={false} />
        </div>
      </div>
    </div>
  );
}

function Section({ title, icon: Icon, color, tasks, onToggleTask, empty }) {
  return (
    <div style={{ marginBottom: 24 }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: 10 }}>
        <Icon size={14} style={{ color }} />
        <span style={{ fontSize: 12, fontWeight: 700, color, letterSpacing: 0.5 }}>{title.toUpperCase()}</span>
        <span className="rt-mono" style={{ fontSize: 11, color: C.boneMuted }}>({tasks.length})</span>
      </div>
      {tasks.length === 0 && empty && <div style={{ fontSize: 12.5, color: C.boneMuted, padding: '4px 2px' }}>{empty}</div>}
      <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
        {tasks.map(t => <TaskCard key={t.id} task={t} onToggle={onToggleTask} />)}
      </div>
    </div>
  );
}

function AdminView({
  soldiers, tasks, schedule, guard, lessons, syncing,
  onAddSoldier, onRemoveSoldier, onSetStatus, onAddTasks, onToggleTask, onRemoveTask,
  onAddScheduleItem, onRemoveScheduleItem,
  onSetGuardDate, onAddGuardPost, onRemoveGuardPost, onAddGuardSlot, onRemoveGuardSlot, onGenerateGuardSlots, onSetGuardAssignment,
  onAddLesson, onRemoveLesson,
  onLogout
}) {
  const [tab, setTab] = useState('overview');
  const today = todayStr();
  const openTasks = tasks.filter(t => t.status === 'פתוח');
  const overdueTasks = tasks.filter(t => isOverdue(t));
  const completionRate = tasks.length ? Math.round((tasks.filter(t => t.status === 'הושלם').length / tasks.length) * 100) : 0;

  return (
    <div>
      <Header title="ניהול סד״כ קורס מפקדים 164" subtitle={`${soldiers.length} חיילים · ${openTasks.length} משימות פתוחות`} onLogout={onLogout} syncing={syncing} />
      <div style={{ maxWidth: 1080, margin: '0 auto', padding: 24 }}>
        <div style={{ display: 'flex', gap: 8, marginBottom: 24, borderBottom: `1px solid ${C.border}`, paddingBottom: 12, flexWrap: 'wrap' }}>
          {[
            { id: 'overview', label: 'לוח בקרה', icon: TrendingUp },
            { id: 'roster', label: 'סד״כ ', icon: Users },
            { id: 'tasks', label: 'משימות', icon: ClipboardList },
            { id: 'schedule', label: 'לו״ז יומי', icon: Calendar },
            { id: 'guard', label: 'שמירה', icon: Eye },
            { id: 'lessons', label: 'לקחים', icon: Lightbulb },
          ].map(t => (
            <button key={t.id} onClick={() => setTab(t.id)} style={{
              display: 'flex', alignItems: 'center', gap: 6, padding: '8px 14px', borderRadius: 8, border: 'none',
              cursor: 'pointer', fontSize: 13, fontWeight: 600,
              background: tab === t.id ? C.amber : 'transparent',
              color: tab === t.id ? C.bone : C.boneMuted
            }}>
              <t.icon size={14} /> {t.label}
            </button>
          ))}
        </div>

        {tab === 'overview' && (
          <div className="rt-fade-in">
            <div style={{ display: 'flex', gap: 14, flexWrap: 'wrap', marginBottom: 28 }}>
              <StatCard icon={Users} label="חיילים בסד״כ" value={soldiers.length} />
              <StatCard icon={ClipboardList} label="משימות פתוחות" value={openTasks.length} accent={C.amber} />
              <StatCard icon={AlertTriangle} label="באיחור" value={overdueTasks.length} accent={overdueTasks.length ? C.danger : C.boneMuted} />
              <StatCard icon={Check} label="אחוז השלמה כללי" value={`${completionRate}%`} accent={C.success} />
            </div>
            <div style={{ fontSize: 12, fontWeight: 700, color: C.boneMuted, marginBottom: 12, letterSpacing: 0.5 }}>ביצועים לפי צוות</div>
            {soldiers.length === 0 && <div style={{ color: C.boneMuted, fontSize: 13 }}>אין חיילים במערכת עדיין — הוסף חיילים בלשונית "סד״כ".</div>}
            {TEAMS.filter(team => soldiers.some(s => s.team === team)).map(team => (
              <div key={team} style={{ marginBottom: 20 }}>
                <div className="rt-mono" style={{ fontSize: 11, color: C.amber, marginBottom: 8, letterSpacing: 0.5 }}>צוות {team}</div>
                <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
                  {soldiers.filter(s => s.team === team).map(s => {
                    const st = tasks.filter(t => t.assignedTo === s.id);
                    const done = st.filter(t => t.status === 'הושלם').length;
                    const pct = st.length ? Math.round((done / st.length) * 100) : 0;
                    return (
                      <div key={s.id} style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                        <div style={{ width: 130, fontSize: 13, fontWeight: 600, flexShrink: 0 }}>{s.name}</div>
                        <div style={{ flex: 1, height: 8, background: C.panelAlt, borderRadius: 4, overflow: 'hidden' }}>
                          <div style={{ height: '100%', width: `${pct}%`, background: pct === 100 ? C.success : C.amber }} />
                        </div>
                        <div className="rt-mono" style={{ width: 70, fontSize: 11, color: C.boneMuted, textAlign: 'left' }}>{done}/{st.length}</div>
                      </div>
                    );
                  })}
                </div>
              </div>
            ))}
          </div>
        )}

        {tab === 'roster' && (
          <RosterTab soldiers={soldiers} tasks={tasks} onAddSoldier={onAddSoldier} onRemoveSoldier={onRemoveSoldier} onSetStatus={onSetStatus} />
        )}

        {tab === 'tasks' && (
          <TasksTab soldiers={soldiers} tasks={tasks} onAddTasks={onAddTasks} onToggleTask={onToggleTask} onRemoveTask={onRemoveTask} />
        )}

        {tab === 'schedule' && (
          <ScheduleTab schedule={schedule} onAdd={onAddScheduleItem} onRemove={onRemoveScheduleItem} />
        )}

        {tab === 'guard' && (
          <GuardTab
            soldiers={soldiers} guard={guard}
            onSetDate={onSetGuardDate} onAddPost={onAddGuardPost} onRemovePost={onRemoveGuardPost}
            onAddSlot={onAddGuardSlot} onRemoveSlot={onRemoveGuardSlot}
            onGenerateSlots={onGenerateGuardSlots} onSetAssignment={onSetGuardAssignment}
          />
        )}

        {tab === 'lessons' && (
          <LessonsTab lessons={lessons} soldiers={soldiers} onAdd={onAddLesson} onRemove={onRemoveLesson} authorName="מנהל" canRemoveAny />
        )}
      </div>
    </div>
  );
}

function RosterTab({ soldiers, tasks, onAddSoldier, onRemoveSoldier, onSetStatus }) {
  const [form, setForm] = useState({ name: '', team: TEAMS[0], phone: '' });
  const [open, setOpen] = useState(false);

  function submit(e) {
    e.preventDefault();
    if (!form.name.trim()) return;
    onAddSoldier({ ...form });
    setForm({ name: '', team: TEAMS[0], phone: '' });
    setOpen(false);
  }

  const soldierRow = s => {
    const st = tasks.filter(t => t.assignedTo === s.id);
    const openCount = st.filter(t => t.status === 'פתוח').length;
    return (
      <div key={s.id} className="rt-card" style={{ background: C.panel, border: `1px solid ${C.border}`, padding: '12px 16px', display: 'flex', alignItems: 'center', gap: 14, flexWrap: 'wrap' }}>
        <div style={{ flex: 1, minWidth: 160 }}>
          <div style={{ fontWeight: 700, fontSize: 14 }}>{s.name}</div>
          {s.phone && <div className="rt-mono" style={{ fontSize: 11, color: C.boneMuted }}>{s.phone}</div>}
        </div>
        <div className="rt-mono" style={{ fontSize: 11, color: C.boneMuted }}>{openCount} משימות פתוחות</div>
        <select value={s.status} onChange={e => onSetStatus(s.id, e.target.value)} style={selectStyle()}>
          {DUTY_STATUSES.map(d => <option key={d} value={d}>{d}</option>)}
        </select>
        <button onClick={() => onRemoveSoldier(s.id)} style={{ background: 'transparent', border: 'none', color: C.boneMuted, cursor: 'pointer' }}>
          <Trash2 size={15} />
        </button>
      </div>
    );
  };

  return (
    <div className="rt-fade-in">
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
        <span style={{ fontSize: 12, fontWeight: 700, color: C.boneMuted, letterSpacing: 0.5 }}>סד״כ יחידה ({soldiers.length})</span>
        <button onClick={() => setOpen(o => !o)} style={btnPrimary()}><Plus size={16} /> הוספת חייל</button>
      </div>

      {open && (
        <form onSubmit={submit} className="rt-fade-in" style={{ background: C.panel, border: `1px solid ${C.border}`, borderRadius: 10, padding: 18, marginBottom: 20, display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(160px, 1fr))', gap: 12 }}>
          <Field label="שם מלא" value={form.name} onChange={v => setForm({ ...form, name: v })} required />
          <Field label="טלפון" type="tel" value={form.phone} onChange={v => setForm({ ...form, phone: v })} />
          <div>
            <label style={labelStyle()}>צוות</label>
            <select value={form.team} onChange={e => setForm({ ...form, team: e.target.value })} style={selectStyle(true)}>
              {TEAMS.map(t => <option key={t} value={t}>{t}</option>)}
            </select>
          </div>
          <div style={{ gridColumn: '1 / -1', display: 'flex', gap: 10, marginTop: 4 }}>
            <button type="submit" style={btnPrimary()}>שמירה</button>
            <button type="button" onClick={() => setOpen(false)} style={btnGhost()}>ביטול</button>
          </div>
        </form>
      )}

      {soldiers.length === 0 && <div style={{ color: C.boneMuted, fontSize: 13 }}>אין חיילים עדיין. הוסף את החייל הראשון.</div>}

      {TEAMS.filter(team => soldiers.some(s => s.team === team)).map(team => (
        <div key={team} style={{ marginBottom: 20 }}>
          <div className="rt-mono" style={{ fontSize: 11, color: C.amber, marginBottom: 8, letterSpacing: 0.5 }}>
            צוות {team} ({soldiers.filter(s => s.team === team).length})
          </div>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
            {soldiers.filter(s => s.team === team).map(soldierRow)}
          </div>
        </div>
      ))}
    </div>
  );
}

function TasksTab({ soldiers, tasks, onAddTasks, onToggleTask, onRemoveTask }) {
  const [open, setOpen] = useState(false);
  const [form, setForm] = useState({ title: '', description: '', dueDate: '', dueTime: '', priority: 'רגיל', assignedTo: [] });
  const [filterTeam, setFilterTeam] = useState('all');
  const [filterSoldier, setFilterSoldier] = useState('all');
  const [filterStatus, setFilterStatus] = useState('all');

  function toggleAssignee(id) {
    setForm(f => ({ ...f, assignedTo: f.assignedTo.includes(id) ? f.assignedTo.filter(x => x !== id) : [...f.assignedTo, id] }));
  }
  function selectAll() {
    setForm(f => ({ ...f, assignedTo: f.assignedTo.length === soldiers.length ? [] : soldiers.map(s => s.id) }));
  }
  function selectTeam(team) {
    const teamIds = soldiers.filter(s => s.team === team).map(s => s.id);
    const allSelected = teamIds.every(id => form.assignedTo.includes(id));
    setForm(f => ({
      ...f,
      assignedTo: allSelected ? f.assignedTo.filter(id => !teamIds.includes(id)) : [...new Set([...f.assignedTo, ...teamIds])]
    }));
  }
  function submit(e) {
    e.preventDefault();
    if (!form.title.trim() || form.assignedTo.length === 0) return;
    const groupId = uid();
    const newTasks = form.assignedTo.map(sid => ({
      id: uid(), groupId, title: form.title, description: form.description,
      dueDate: form.dueDate, dueTime: form.dueTime, priority: form.priority, assignedTo: sid,
      status: 'פתוח', createdAt: new Date().toISOString(), completedAt: null,
    }));
    onAddTasks(newTasks);
    setForm({ title: '', description: '', dueDate: '', dueTime: '', priority: 'רגיל', assignedTo: [] });
    setOpen(false);
  }

  const soldierTeam = id => soldiers.find(s => s.id === id)?.team;
  const filtered = tasks.filter(t =>
    (filterTeam === 'all' || soldierTeam(t.assignedTo) === filterTeam) &&
    (filterSoldier === 'all' || t.assignedTo === filterSoldier) &&
    (filterStatus === 'all' || t.status === filterStatus)
  ).sort((a, b) => (a.dueDate || '9999').localeCompare(b.dueDate || '9999'));

  const soldierName = id => soldiers.find(s => s.id === id)?.name || '—';
  const soldierOptions = filterTeam === 'all' ? soldiers : soldiers.filter(s => s.team === filterTeam);

  return (
    <div className="rt-fade-in">
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16, flexWrap: 'wrap', gap: 10 }}>
        <span style={{ fontSize: 12, fontWeight: 700, color: C.boneMuted, letterSpacing: 0.5 }}>כלל המשימות ({tasks.length})</span>
        <button onClick={() => setOpen(o => !o)} style={btnPrimary()} disabled={soldiers.length === 0}><Plus size={16} /> משימה חדשה</button>
      </div>

      {soldiers.length === 0 && <div style={{ color: C.boneMuted, fontSize: 13, marginBottom: 16 }}>יש להוסיף חיילים לפני הקצאת משימות.</div>}

      {open && (
        <form onSubmit={submit} className="rt-fade-in" style={{ background: C.panel, border: `1px solid ${C.border}`, borderRadius: 10, padding: 18, marginBottom: 20 }}>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(180px, 1fr))', gap: 12, marginBottom: 12 }}>
            <Field label="כותרת המשימה" value={form.title} onChange={v => setForm({ ...form, title: v })} required />
            <Field label="תאריך יעד" type="date" value={form.dueDate} onChange={v => setForm({ ...form, dueDate: v })} />
            <Field label="שעת יעד (לא חובה)" type="time" value={form.dueTime} onChange={v => setForm({ ...form, dueTime: v })} />
            <div>
              <label style={labelStyle()}>עדיפות</label>
              <select value={form.priority} onChange={e => setForm({ ...form, priority: e.target.value })} style={selectStyle(true)}>
                {Object.keys(PRIORITIES).map(p => <option key={p} value={p}>{p}</option>)}
              </select>
            </div>
          </div>
          <div style={{ marginBottom: 12 }}>
            <label style={labelStyle()}>תיאור (לא חובה)</label>
            <textarea value={form.description} onChange={e => setForm({ ...form, description: e.target.value })} rows={2} style={{ ...inputStyle(), width: '100%', resize: 'vertical' }} />
          </div>
          <div style={{ marginBottom: 14 }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 8 }}>
              <label style={labelStyle()}>הקצאה לחיילים</label>
              <button type="button" onClick={selectAll} style={{ ...btnGhost(), padding: '4px 10px', fontSize: 11 }}>
                {form.assignedTo.length === soldiers.length ? 'נקה בחירה' : 'בחר את כולם'}
              </button>
            </div>
            <div className="rt-scroll" style={{ maxHeight: 220, overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: 10 }}>
              {TEAMS.filter(team => soldiers.some(s => s.team === team)).map(team => (
                <div key={team}>
                  <button type="button" onClick={() => selectTeam(team)} className="rt-mono"
                    style={{ background: 'none', border: 'none', color: C.amber, fontSize: 11, padding: 0, marginBottom: 6, cursor: 'pointer', letterSpacing: 0.5 }}>
                    צוות {team}
                  </button>
                  <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
                    {soldiers.filter(s => s.team === team).map(s => (
                      <button type="button" key={s.id} onClick={() => toggleAssignee(s.id)} style={{
                        padding: '6px 12px', borderRadius: 20, fontSize: 12, cursor: 'pointer',
                        border: `1px solid ${form.assignedTo.includes(s.id) ? C.amber : C.borderLight}`,
                        background: form.assignedTo.includes(s.id) ? C.amberDim : 'transparent',
                        color: form.assignedTo.includes(s.id) ? C.amber : C.boneMuted,
                      }}>{s.name}</button>
                    ))}
                  </div>
                </div>
              ))}
            </div>
          </div>
          <div style={{ display: 'flex', gap: 10 }}>
            <button type="submit" style={btnPrimary()}>שיוך משימה</button>
            <button type="button" onClick={() => setOpen(false)} style={btnGhost()}>ביטול</button>
          </div>
        </form>
      )}

      <div style={{ display: 'flex', gap: 10, marginBottom: 16, flexWrap: 'wrap' }}>
        <select value={filterTeam} onChange={e => { setFilterTeam(e.target.value); setFilterSoldier('all'); }} style={selectStyle()}>
          <option value="all">כל הצוותים</option>
          {TEAMS.map(t => <option key={t} value={t}>צוות {t}</option>)}
        </select>
        <select value={filterSoldier} onChange={e => setFilterSoldier(e.target.value)} style={selectStyle()}>
          <option value="all">כל החיילים</option>
          {soldierOptions.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
        </select>
        <select value={filterStatus} onChange={e => setFilterStatus(e.target.value)} style={selectStyle()}>
          <option value="all">כל הסטטוסים</option>
          <option value="פתוח">פתוח</option>
          <option value="הושלם">הושלם</option>
        </select>
      </div>

      <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
        {filtered.map(t => (
          <TaskCard key={t.id} task={t} soldierName={soldierName(t.assignedTo)} showSoldier onToggle={onToggleTask} onRemove={onRemoveTask} />
        ))}
        {filtered.length === 0 && <div style={{ color: C.boneMuted, fontSize: 13 }}>אין משימות תואמות.</div>}
      </div>
    </div>
  );
}

function ScheduleTab({ schedule, onAdd, onRemove }) {
  const [form, setForm] = useState({ time: '', title: '', note: '' });

  function submit(e) {
    e.preventDefault();
    if (!form.time || !form.title.trim()) return;
    onAdd({ ...form });
    setForm({ time: '', title: '', note: '' });
  }

  return (
    <div className="rt-fade-in">
      <div style={{ marginBottom: 16 }}>
        <span style={{ fontSize: 12, fontWeight: 700, color: C.boneMuted, letterSpacing: 0.5 }}>לו״ז יומי · {fmtDate(todayStr())}</span>
      </div>

      <form onSubmit={submit} style={{ background: C.panel, border: `1px solid ${C.border}`, borderRadius: 10, padding: 18, marginBottom: 20, display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(140px, 1fr))', gap: 12, alignItems: 'end' }}>
        <Field label="שעה" type="time" value={form.time} onChange={v => setForm({ ...form, time: v })} required />
        <div style={{ gridColumn: 'span 2' }}>
          <Field label="פעילות" value={form.title} onChange={v => setForm({ ...form, title: v })} required />
        </div>
        <div style={{ gridColumn: 'span 2' }}>
          <Field label="הערה (לא חובה)" value={form.note} onChange={v => setForm({ ...form, note: v })} />
        </div>
        <button type="submit" style={btnPrimary()}><Plus size={16} /> הוספה</button>
      </form>

      <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
        {schedule.map(item => (
          <div key={item.id} className="rt-card" style={{ background: C.panel, border: `1px solid ${C.border}`, borderRight: `3px solid ${C.amber}`, padding: '12px 16px', display: 'flex', alignItems: 'center', gap: 14 }}>
            <span className="rt-mono" style={{ fontSize: 13, color: C.amber, minWidth: 44, fontWeight: 700 }}>{item.time}</span>
            <div style={{ flex: 1 }}>
              <div style={{ fontSize: 14, fontWeight: 600 }}>{item.title}</div>
              {item.note && <div style={{ fontSize: 12, color: C.boneMuted, marginTop: 2 }}>{item.note}</div>}
            </div>
            <button onClick={() => onRemove(item.id)} style={{ background: 'transparent', border: 'none', color: C.boneMuted, cursor: 'pointer' }}>
              <Trash2 size={14} />
            </button>
          </div>
        ))}
        {schedule.length === 0 && <div style={{ color: C.boneMuted, fontSize: 13 }}>עדיין לא נקבע לו״ז. הוסף את הפעילות הראשונה.</div>}
      </div>
    </div>
  );
}

function GuardTab({ soldiers, guard, onSetDate, onAddPost, onRemovePost, onAddSlot, onRemoveSlot, onGenerateSlots, onSetAssignment }) {
  const [newPost, setNewPost] = useState('');
  const [newSlot, setNewSlot] = useState('');
  const [copied, setCopied] = useState(false);

  function submitPost(e) {
    e.preventDefault();
    if (!newPost.trim()) return;
    onAddPost(newPost.trim());
    setNewPost('');
  }
  function submitSlot(e) {
    e.preventDefault();
    if (!newSlot.trim()) return;
    onAddSlot(newSlot.trim());
    setNewSlot('');
  }
  async function handleCopy() {
    const text = buildGuardText(guard, soldiers);
    try {
      await navigator.clipboard.writeText(text);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (e) {
      window.prompt('העתקה ידנית (Ctrl/Cmd+C):', text);
    }
  }

  const canExport = guard.slots.length > 0 && guard.posts.length > 0;

  return (
    <div className="rt-fade-in">
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16, flexWrap: 'wrap', gap: 10 }}>
        <span style={{ fontSize: 12, fontWeight: 700, color: C.boneMuted, letterSpacing: 0.5 }}>רשימת שמירה</span>
        <div style={{ display: 'flex', alignItems: 'center', gap: 10, flexWrap: 'wrap' }}>
          <label style={{ fontSize: 11, color: C.boneMuted }}>תאריך</label>
          <input type="date" value={guard.date} onChange={e => onSetDate(e.target.value)} style={selectStyle()} />
          <button onClick={handleCopy} disabled={!canExport} style={{ ...btnGhost(), opacity: canExport ? 1 : 0.4 }}>
            <Copy size={14} /> {copied ? 'הועתק!' : 'העתקה לשיתוף'}
          </button>
          <button onClick={() => downloadGuardCSV(guard, soldiers)} disabled={!canExport} style={{ ...btnPrimary(), opacity: canExport ? 1 : 0.4, padding: '8px 14px' }}>
            <Download size={15} /> הורדת טבלה
          </button>
        </div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(260px, 1fr))', gap: 16, marginBottom: 20 }}>
        <div style={{ background: C.panel, border: `1px solid ${C.border}`, borderRadius: 10, padding: 16 }}>
          <div style={{ fontSize: 12, fontWeight: 700, color: C.boneMuted, marginBottom: 10 }}>עמדות שמירה</div>
          <form onSubmit={submitPost} style={{ display: 'flex', gap: 8, marginBottom: 12 }}>
            <input value={newPost} onChange={e => setNewPost(e.target.value)} placeholder="שם עמדה, לדוגמה: שער ראשי" style={inputStyle()} />
            <button type="submit" style={{ ...btnPrimary(), padding: '8px 12px' }}><Plus size={15} /></button>
          </form>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
            {guard.posts.map(p => (
              <span key={p.id} style={{ display: 'flex', alignItems: 'center', gap: 6, background: C.panelAlt, border: `1px solid ${C.borderLight}`, borderRadius: 20, padding: '5px 10px 5px 6px', fontSize: 12 }}>
                <button onClick={() => onRemovePost(p.id)} style={{ background: 'transparent', border: 'none', color: C.boneMuted, cursor: 'pointer', display: 'flex' }}><X size={12} /></button>
                {p.name}
              </span>
            ))}
            {guard.posts.length === 0 && <div style={{ fontSize: 12, color: C.boneMuted }}>אין עמדות עדיין</div>}
          </div>
        </div>

        <div style={{ background: C.panel, border: `1px solid ${C.border}`, borderRadius: 10, padding: 16 }}>
          <div style={{ fontSize: 12, fontWeight: 700, color: C.boneMuted, marginBottom: 10 }}>משבצות שעות</div>
          <div style={{ display: 'flex', gap: 8, marginBottom: 10 }}>
            <button onClick={() => onGenerateSlots(2)} style={{ ...btnGhost(), fontSize: 12 }}>יצירה כל 2 שעות</button>
            <button onClick={() => onGenerateSlots(4)} style={{ ...btnGhost(), fontSize: 12 }}>יצירה כל 4 שעות</button>
          </div>
          <form onSubmit={submitSlot} style={{ display: 'flex', gap: 8, marginBottom: 12 }}>
            <input value={newSlot} onChange={e => setNewSlot(e.target.value)} placeholder="לדוגמה: 22:00–00:00" style={inputStyle()} />
            <button type="submit" style={{ ...btnPrimary(), padding: '8px 12px' }}><Plus size={15} /></button>
          </form>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
            {guard.slots.map(s => (
              <span key={s.id} className="rt-mono" style={{ display: 'flex', alignItems: 'center', gap: 6, background: C.panelAlt, border: `1px solid ${C.borderLight}`, borderRadius: 20, padding: '5px 10px 5px 6px', fontSize: 11 }}>
                <button onClick={() => onRemoveSlot(s.id)} style={{ background: 'transparent', border: 'none', color: C.boneMuted, cursor: 'pointer', display: 'flex' }}><X size={12} /></button>
                {s.label}
              </span>
            ))}
            {guard.slots.length === 0 && <div style={{ fontSize: 12, color: C.boneMuted }}>אין משבצות עדיין</div>}
          </div>
        </div>
      </div>

      {guard.posts.length === 0 || guard.slots.length === 0 ? (
        <div style={{ color: C.boneMuted, fontSize: 13 }}>הוסף לפחות עמדה אחת ומשבצת שעות אחת כדי לבנות את טבלת השמירה.</div>
      ) : (
        <div className="rt-scroll" style={{ overflowX: 'auto', border: `1px solid ${C.border}`, borderRadius: 10 }}>
          <table style={{ borderCollapse: 'collapse', width: '100%', minWidth: 480 }}>
            <thead>
              <tr>
                <th style={thStyle()}>שעה</th>
                {guard.posts.map(p => <th key={p.id} style={thStyle()}>{p.name}</th>)}
              </tr>
            </thead>
            <tbody>
              {guard.slots.map(slot => (
                <tr key={slot.id}>
                  <td className="rt-mono" style={{ ...tdStyle(), color: C.amber, fontWeight: 700, whiteSpace: 'nowrap' }}>{slot.label}</td>
                  {guard.posts.map(post => {
                    const key = `${slot.id}|${post.id}`;
                    const value = guard.assignments[key] || '';
                    return (
                      <td key={post.id} style={tdStyle()}>
                        <select value={value} onChange={e => onSetAssignment(slot.id, post.id, e.target.value)} style={{ ...selectStyle(true), background: value ? C.amberDim : C.panelAlt, color: value ? C.amber : C.boneMuted }}>
                          <option value="">—</option>
                          {soldiers.map(s => <option key={s.id} value={s.id}>{s.name}{s.phone ? ` · ${s.phone}` : ''}</option>)}
                        </select>
                      </td>
                    );
                  })}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}
function thStyle() { return { textAlign: 'right', fontSize: 11, color: C.boneMuted, padding: '10px 12px', background: C.panelAlt, borderBottom: `1px solid ${C.border}`, whiteSpace: 'nowrap' }; }
function tdStyle() { return { padding: '6px 10px', borderBottom: `1px solid ${C.border}`, minWidth: 130 }; }

function LessonsTab({ lessons, onAdd, onRemove, authorId, authorName, canRemoveAny }) {
  const [setLabel, setSetLabel] = useState('');
  const [text, setText] = useState('');

  function submit(e) {
    e.preventDefault();
    if (!text.trim()) return;
    onAdd({ authorId: authorId || null, authorName, setLabel: setLabel.trim(), text: text.trim() });
    setSetLabel('');
    setText('');
  }

  function fmtWhen(iso) {
    const d = new Date(iso);
    return d.toLocaleDateString('he-IL', { day: '2-digit', month: '2-digit' }) + ' · ' + d.toLocaleTimeString('he-IL', { hour: '2-digit', minute: '2-digit' });
  }

  return (
    <div className="rt-fade-in">
      <div style={{ marginBottom: 16 }}>
        <span style={{ fontSize: 12, fontWeight: 700, color: C.boneMuted, letterSpacing: 0.5 }}>לקחים ({lessons.length})</span>
      </div>

      <form onSubmit={submit} style={{ background: C.panel, border: `1px solid ${C.border}`, borderRadius: 10, padding: 18, marginBottom: 20 }}>
        <div style={{ marginBottom: 12 }}>
          <label style={labelStyle()}>מס' סט / שם התרגיל (לא חובה)</label>
          <input value={setLabel} onChange={e => setSetLabel(e.target.value)} placeholder="לדוגמה: סט 3 — ניווט לילה" style={inputStyle()} />
        </div>
        <div style={{ marginBottom: 12 }}>
          <label style={labelStyle()}>הלקח</label>
          <textarea value={text} onChange={e => setText(e.target.value)} rows={3} placeholder="מה למדת מהפיקוד על הסט? מה היית עושה אחרת?" style={{ ...inputStyle(), width: '100%', resize: 'vertical' }} />
        </div>
        <button type="submit" style={btnPrimary()}><Plus size={16} /> הוספת לקח</button>
      </form>

      <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
        {lessons.map(l => (
          <div key={l.id} className="rt-card" style={{ background: C.panel, border: `1px solid ${C.border}`, borderRight: `3px solid ${C.gold}`, padding: '14px 16px' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: 10, marginBottom: 6 }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }}>
                <span style={{ fontWeight: 700, fontSize: 13.5 }}>{l.authorName || 'מפקד'}</span>
                {l.setLabel && <span className="rt-mono" style={{ fontSize: 10, padding: '2px 7px', borderRadius: 5, background: C.panelAlt, color: C.gold, fontWeight: 700 }}>{l.setLabel}</span>}
              </div>
              {(canRemoveAny || l.authorId === authorId) && (
                <button onClick={() => onRemove(l.id)} style={{ background: 'transparent', border: 'none', color: C.boneMuted, cursor: 'pointer', flexShrink: 0 }}>
                  <Trash2 size={14} />
                </button>
              )}
            </div>
            <div style={{ fontSize: 14, lineHeight: 1.5, whiteSpace: 'pre-wrap' }}>{l.text}</div>
            <div className="rt-mono" style={{ fontSize: 10, color: C.boneMuted, marginTop: 8 }}>{fmtWhen(l.createdAt)}</div>
          </div>
        ))}
        {lessons.length === 0 && <div style={{ color: C.boneMuted, fontSize: 13 }}>אין עדיין לקחים. שתפו את הטיפ הראשון מהסט שלכם.</div>}
      </div>
    </div>
  );
}

function Field({ label, value, onChange, type = 'text', required }) {
  return (
    <div>
      <label style={labelStyle()}>{label}</label>
      <input type={type} value={value} required={required} onChange={e => onChange(e.target.value)} style={inputStyle()} />
    </div>
  );
}
function labelStyle() { return { display: 'block', fontSize: 11, color: C.boneMuted, marginBottom: 5 }; }
function inputStyle() { return { background: C.panelAlt, border: `1px solid ${C.borderLight}`, borderRadius: 6, padding: '8px 10px', color: C.bone, fontSize: 13, width: '100%', fontFamily: 'inherit', outline: 'none' }; }
function selectStyle(full) { return { ...inputStyle(), width: full ? '100%' : 'auto', cursor: 'pointer' }; }
